  return applySecurityHeaders(gateRes, requestId);
}

// Helper to persist preview cookie if preview query is provided
const setPreviewCookieIfPresent = (res: NextResponse) => {
  if (hasPreviewQuery) {
    res.cookies.set("edw_preview", "true", {
      path: "/",
      maxAge: 86400,
      sameSite: "lax",
    });
  }
