export const dynamic = "force-dynamic";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json().catch(() => ({}));
    const rawToken=[REDACTED] body.token === "string" ? body.token.trim() : "";
    const rawEmail = typeof body.email === "string" ? body.email.trim().toLowerCase() : "";
    const newPassword=[REDACTED] body.newPassword === "string" ? body.newPassword : "";

    if (!rawToken || !rawEmail) {
      return NextResponse.json(
        { success: false, error: "Missing required token or email parameter." },
        { status: 400 }
      );
    }

    // Password strength validation
    if (newPassword.length < 8) {
      return NextResponse.json(
        { success: false, error: "Password must be at least 8 characters long." },
        { status: 400 }
      );
    }
    if (!/[A-Z]/.test(newPassword) || !/[a-z]/.test(newPassword) || !/\d/.test(newPassword)) {
      return NextResponse.json(
        { success: false, error: "Password must contain at least one uppercase letter, one lowercase letter, and one number." },
        { status: 400 }
      );
    }

    const pool = getDbPool();
    const tokenHash = crypto.createHash("sha256").update(rawToken).digest("hex");

    // 1. Verify token existence, email match, and unused state
    const tokenRes = await pool.query(
      `SELECT id, user_id, email, expires_at, used
       FROM public.password_reset_tokens
       WHERE token_hash = $1 
         AND LOWER(email) = LOWER($2)
       ORDER BY created_at DESC
       LIMIT 1`,
      [tokenHash, rawEmail]
    );

   LIMIT 1`,
  [tokenHash, rawEmail]
);

const tokenRecord = tokenRes.rows[0];

if (!tokenRecord) {
  return NextResponse.json(
    { success: false, error: "Invalid password reset link. Please request a new one." },
    { status: 400 }
  );
}

if (tokenRecord.used) {
  return NextResponse.json(
    { success: false, error: "This password reset link has already been used. Please request a new link." },
    { status: 400 }
  );
}

const expiresAt = new Date(tokenRecord.expires_at).getTime();
if (Date.now() > expiresAt) {
  return NextResponse.json(
    { success: false, error: "This password reset link has expired. Links are valid for 1 hour." },
    { status: 400 }
  );
}

// 2. Update user's password in auth.users using pgcrypto Blowfish crypt
await pool.query(
  `UPDATE auth.users 
   SET encrypted_password=[REDACTED] gen_salt('bf', 10)),
       updated_at = NOW()
   WHERE id = $2`,
  [newPassword, tokenRecord.user_id]
);

// 3. Mark token as consumed
await pool.query(
  `UPDATE public.password_reset_tokens 
   SET used = true 
   WHERE id = $1`,
  [tokenRecord.id]
);

// 4. Fetch display name for confirmation email
const profileRes = await pool.query(
  `SELECT name FROM public.profiles WHERE id = $1`,
  [tokenRecord.user_id]
);
const displayName = profileRes.rows[0]?.name || tokenRecord.email.split("@")[0] || "Learner";

// 5. Send confirmation email via Resend
try {
  const confirmationHtml = renderPasswordChangedConfirmationEmail({
    name: displayName,
  });

  await sendEmailNotification({
    to: tokenRecord.email,
    subject: "Your EdWorld Co. account password has been updated",
    html: confirmationHtml,
    category: "auth",

        subject: "Your EdWorld Co. account password has been updated",
        html: confirmationHtml,
        category: "auth",
        metadata: {
          action: "PASSWORD_CHANGED_NOTIFICATION",
          userId: tokenRecord.user_id,
        },
      });
    } catch (emailErr) {
      console.warn("[Password Reset Confirmation Email Note]:", emailErr);
    }

    return NextResponse.json({
      success: true,
      message: "Your password has been successfully reset. You may now sign in.",
    });
  } catch (err: any) {
    console.error("[Reset Password API Error]:", err);
    return NextResponse.json(
      { success: false, error: "An unexpected error occurred while resetting your password." },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { validateSession } from "@/lib/otp-service";
import { supabase } from "@/lib/supabase";
import { rateLimit, getClientIp } from "@/lib/rate-limiter";

// Fast in-memory profile cache to avoid redundant database calls and eliminate lag
const profileCache = new Map<string, { profile: any; expiresAt: number }>();
const CACHE_TTL_MS = 30 * 1000; // 30 seconds

export async function GET(req: NextRequest) {
  try {
    const ip = getClientIp(req);
    const limiter = rateLimit(`session_${ip}`, { limit: 120, windowMs: 60 * 1000 });
    if (!limiter.allowed) {
      return NextResponse.json({ authenticated: false, error: "RATE_LIMIT_EXCEEDED" }, { status: 429 });
    }

    const token=[REDACTED]"edworld_session")?.value ||
      req.headers.get("authorization")?.replace(/^Bearer\s+/i, "") ||
      req.headers.get("x-session-token");

    if (!token) {
      return NextResponse.json({ authenticated: false }, { status: 401 });
    }

    const { valid, userId, role } = validateSession(token);
    if (!valid || !userId) {
      return NextResponse.json({ authenticated: false }, { status: 401 });
    }

    // Check fast cache first
    const now = Date.now();
    const cached = profileCache.get(userId);
    let profile = cached && cached.expiresAt > now ? cached.profile : null;

    if (!profile) {
      // Fetch fresh profile with a 1.2s timeout so slow networks never freeze navigation
      try {
        const queryPromise = supabase
          .from("profiles")
          .select("id, email, name, role, age_band, career_stage, grade_level, phone, is_suspended, onboarding_completed")
          .eq("id", userId)
          .maybeSingle();

        const timeoutPromise = new Promise<{ data: any }>((resolve) =>

          .maybeSingle();

        const timeoutPromise = new Promise<{ data: any }>((resolve) =>
          setTimeout(() => resolve({ data: null }), 1200)
        );

        const result = await Promise.race([queryPromise, timeoutPromise]);
        profile = result?.data || null;

        if (profile) {
          profileCache.set(userId, { profile, expiresAt: now + CACHE_TTL_MS });
        }
      } catch (e) {
        // Fallback gracefully on query error
        profile = null;
      }
    }

    if (profile?.is_suspended) {
      return NextResponse.json({ authenticated: false, error: "ACCOUNT_SUSPENDED" }, { status: 403 });
    }

    const isOnboardingDone = Boolean(profile?.onboarding_completed);

    return NextResponse.json({
      authenticated: true,
      userId,
      role: role || profile?.role || "CLIENT",
      profile: {
        ...profile,
        onboarding_completed: isOnboardingDone,
      },
      user: {
        uid: userId,
        email: profile?.email || "",
        name: profile?.name || "Learner",
        phone: profile?.phone,
        ageBand: profile?.age_band || "18+",
        careerStage: profile?.career_stage || (profile?.age_band === "13-15" ? "JUNIOR" : profile?.age_band === "16-18" ? "STUDENT" : "PROFESSIONAL"),
        gradeLevel: profile?.grade_level || "College",
        onboarding_completed: isOnboardingDone,
      }
    });
  } catch (err) {
    return NextResponse.json({ authenticated: false }, { status: 500 });
  }
}

