import { NextRequest, NextResponse } from "next/server";
import { supabase } from "@/lib/supabase";

export const dynamic = "force-dynamic";

export async function PATCH(req: NextRequest) {
  try {
    const body = await req.json().catch(() => ({}));
    const { userId, taskId, status, notes } = body;

    if (!userId || !taskId || !status) {
      return NextResponse.json({ error: "Missing required fields: userId, taskId, status" }, { status: 400 });
    }

    const updatePayload: any = {
      status,
      updated_at: new Date().toISOString()
    };

    if (status === "completed") {
      updatePayload.completed_at = new Date().toISOString();
    }
    if (notes !== undefined) {
      updatePayload.notes = notes;
    }

    const { data: updatedTask, error } = await supabase
      .from("daily_plans")
      .update(updatePayload)
      .eq("id", taskId)
      .eq("user_id", userId)
      .select("*")
      .maybeSingle();

    if (error) {
      console.warn("[Daily Task Update Note]:", error.message);
    }

    // Award Gamification Points if task completed
    if (status === "completed") {
      try {
        const { data: stats } = await supabase
          .from("user_stats")
          .select("points, current_streak")
          .eq("user_id", userId)
          .maybeSingle();

        if (stats) {
          await supabase
            .from("user_stats")
            .update({
              points: (stats.points || 0) + 15,
              updated_at: new Date().toISOString()
            })
            .eq("user_id", userId);
        }
      } catch (gErr) {
        console.warn("Gamification award note:", gErr);
      }
    }

    return NextResponse.json({
      success: true,
      task: updatedTask || { id: taskId, user_id: userId, status, ...updatePayload }
    });
  } catch (err: any) {
    console.error("[Daily Task PATCH Error]:", err);

    });
  } catch (err: any) {
    console.error("[Daily Task PATCH Error]:", err);
    return NextResponse.json({ error: err.message || "Failed to update task status" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getDbPool } from "@/lib/db-server";

export const dynamic = "force-dynamic";

export async function GET(
  req: NextRequest,
  { params }: { params: { certificateId: string } }
) {
  try {
    const rawId = (params.certificateId || "").trim();
    if (!rawId) {
      return NextResponse.json({ success: false, error: "Missing certificate ID" }, { status: 400 });
    }

    const pool = getDbPool();
    const client = await pool.connect();

    try {
      // 1. Try edbuild_certificates first
      let certRes = await client.query(
        `SELECT c.*, g.problem_statement, g.submission_repo_url, g.submission_live_url
         FROM public.edbuild_certificates c
         LEFT JOIN public.edbuild_groups g ON g.id = c.group_id
         WHERE LOWER(c.certificate_code) = LOWER($1) OR c.id::text = $1
         LIMIT 1;`,
        [rawId]
      );

      if (certRes.rows.length > 0) {
        return NextResponse.json({
          success: true,
          certificate: certRes.rows[0],
          type: "edbuild",
        });
      }

      // 2. Fallback to course_certificates
      const courseCertRes = await client.query(
        `SELECT * FROM public.course_certificates 
         WHERE LOWER(certificate_code) = LOWER($1) OR id::text = $1
         LIMIT 1;`,
        [rawId]
      );

      if (courseCertRes.rows.length > 0) {
        const c = courseCertRes.rows[0];
        return NextResponse.json({
          success: true,
          certificate: {
            certificate_code: c.certificate_code,
            recipient_name: c.recipient_name,
            project_name: c.course_title,
            issued_at: c.issued_at,
            verification_hash: c.verification_hash,
          },
          type: "course",
        });
      }

      return NextResponse.json(
        { success: false, error: "Authentic certificate not found" },
        { status: 404 }
      );
    } finally {
      client.release();
    }
  } catch (err: any) {
    console.error("[CertificateAPI:GET] Error:", err);
    return NextResponse.json(

  } catch (err: any) {
    console.error("[CertificateAPI:GET] Error:", err);
    return NextResponse.json(
      { success: false, error: err.message || "Failed to retrieve certificate" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { queryDb } from "@/lib/db-server";

export const dynamic = "force-dynamic";

export async function GET(
  req: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const rawId = params.id;
    if (!rawId) {
      return NextResponse.json({ success: false, error: "Certificate ID or code is required" }, { status: 400 });
    }

    const cleanId = rawId.trim();

    // Query either by certificate_code (case-insensitive) or by UUID
    const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(cleanId);

    const sql = isUuid
      ? `SELECT c.*, co.skills, co.duration_weeks, co.level
         FROM public.course_certificates c
         LEFT JOIN public.courses co ON c.course_id = co.id
         WHERE c.id = $1
         LIMIT 1`
      : `SELECT c.*, co.skills, co.duration_weeks, co.level
         FROM public.course_certificates c
         LEFT JOIN public.courses co ON c.course_id = co.id
         WHERE LOWER(c.certificate_code) = LOWER($1)
         LIMIT 1`;

    const { rows } = await queryDb(sql, [cleanId]);

    if (rows.length === 0) {
      return NextResponse.json(
        { success: false, error: "Certificate not found or invalid verification code" },
        { status: 404 }
      );
    }

    const cert = rows[0];

    return NextResponse.json({
      success: true,
      verified: true,
      certificate: {
        id: cert.id,
        certificateCode: cert.certificate_code,
        recipientName: cert.recipient_name,
        courseTitle: cert.course_title,
        courseCategory: cert.course_category,
        courseSlug: cert.course_slug,
        scorePercentage: cert.score_percentage,
        skills: cert.skills || [],
        durationWeeks: cert.duration_weeks || 6,
        level: cert.level || "Intermediate",
        verificationHash: cert.verification_hash,
        issuedAt: cert.issued_at,
        organization: "Edworld Co.",

        verificationHash: cert.verification_hash,
        issuedAt: cert.issued_at,
        organization: "Edworld Co.",
        accreditation: "Verified Career & Engineering Academy",
      },
    });
  } catch (err: any) {
    console.error("[API Certificate Verify Error]:", err);
    return NextResponse.json(
      { success: false, error: "Failed to verify certificate" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { ClaudeOrchestrator, ClaudeAnalysisRequest } from "@/lib/ai/claude-orchestrator";
import { createClient } from "@/lib/supabase/server";

export const dynamic = "force-dynamic";

export type ClaudeAnalysisType = 
  | "analyze_resume" 
  | "analyze_job_match" 
  | "analyze_interview" 
  | "analyze_language" 
  | "analyze_project" 
  | "analyze_coding_attempt" 
  | "generate_personalized_feedback" 
  | "generate_practice_plan"
  | "code_review" 
  | "resume_ats" 
  | "project_architecture" 
  | "appraisal_performance" 
  | "interview_response"
  | "problem_solution";

export async function POST(req: NextRequest) {
  try {
    const supabase = createClient();
    const { data: { user } } = await supabase.auth.getUser();

    const body = await req.json().catch(() => ({}));
    const { 
      type = "analyze_resume", 
      content, 
      metadata = {}, 
      inputReference,
      bypassCache = false
    }: {
      type: ClaudeAnalysisType;
      content: string;
      metadata?: Record<string, any>;
      inputReference?: Record<string, any>;
      bypassCache?: boolean;
    } = body;

    if (!content || typeof content !== "string" || content.trim().length === 0) {
      return NextResponse.json({ error: "Content is required for Claude analysis." }, { status: 400 });
    }

    // Map legacy names to canonical Phase 33 analysis types
    let canonicalType: ClaudeAnalysisRequest["analysisType"] = "analyze_resume";
    let feature: ClaudeAnalysisRequest["feature"] = "resume";

    if (type === "analyze_job_match" || type === "resume_ats") {
      canonicalType = "analyze_job_match";
      feature = "ats";
    } else if (type === "analyze_interview" || type === "interview_response") {
      canonicalType = "analyze_interview";
      feature = "interview";
    } else if (type === "analyze_language") {
      canonicalType = "analyze_language";
      feature = "language";

    } else if (type === "analyze_language") {
      canonicalType = "analyze_language";
      feature = "language";
    } else if (type === "analyze_project" || type === "project_architecture") {
      canonicalType = "analyze_project";
      feature = "project";
    } else if (type === "analyze_coding_attempt" || type === "code_review" || type === "problem_solution") {
      canonicalType = "analyze_coding_attempt";
      feature = "coding";
    } else if (type === "generate_personalized_feedback" || type === "appraisal_performance") {
      canonicalType = "generate_personalized_feedback";
      feature = "career";
    } else if (type === "generate_practice_plan") {
      canonicalType = "generate_practice_plan";
      feature = "career";
    }

    const userId = user?.id || req.headers.get("x-user-id") || "guest";

    const res = await ClaudeOrchestrator.analyze({
      userId,
      feature,
      analysisType: canonicalType,
      content: content.trim(),
      metadata,
      inputReference,
      bypassCache
    });

    if (res.success && res.data) {
      return NextResponse.json({
        success: true,
        type: canonicalType,
        source: "claude-orchestrator",
        analysis: res.data,
        timestamp: new Date().toISOString()
      });
    }

    return NextResponse.json({
      success: false,
      error: res.error || "Failed to execute Claude analysis."
    }, { status: res.statusCode || 500 });

  } catch (error: any) {
    console.error("[Claude Analysis Route Error]:", error);
    return NextResponse.json({ error: error.message || "Failed to execute Claude analysis." }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { forwardContactInquiry } from "@/lib/email-service";
import { supabase } from "@/lib/supabase";
import { rateLimit, getClientIp } from "@/lib/rate-limiter";
import { logger } from "@/lib/logger";

export const dynamic = "force-dynamic";

export async function POST(req: NextRequest) {
  const requestId = req.headers.get("x-request-id") || `req-${Date.now()}`;
  const log = logger.child({ request_id: requestId, route: "/api/contact", service: "email" });

  // Rate limit: 5 contact submissions per IP per minute to prevent spam
  const ip = getClientIp(req);
  const rl = rateLimit(`contact:${ip}`, { limit: 5, windowMs: 60_000 });
  if (!rl.allowed) {
    log.warn("Contact rate limit exceeded", { ip });
    return NextResponse.json(
      { success: false, error: "Too many submissions. Please wait a moment before trying again." },
      {
        status: 429,
        headers: {
          "Retry-After": String(Math.ceil((rl.reset - Date.now()) / 1000)),
          "x-request-id": requestId,
        },
      }
    );
  }

  try {
    const body = await req.json();
    const { name, email, category, message } = body;

    if (!name || !email || !message) {
      return NextResponse.json(
        { success: false, error: "Please provide your name, email, and message." },
        { status: 400 }
      );
    }

    // Forward to [EMAIL]
    await forwardContactInquiry({
      name: name.trim(),
      email: email.trim(),
      category: category || "General Support",
      message: message.trim(),
      ip: req.headers.get("x-forwarded-for") || undefined,
    });

    // Optionally record in database inquiries table if exists
    try {
      await supabase.from("support_inquiries").insert({
        name: name.trim(),
        email: email.trim(),

      await supabase.from("support_inquiries").insert({
        name: name.trim(),
        email: email.trim(),
        category: category || "General Support",
        message: message.trim(),
        status: "NEW",
        destination_email: "[EMAIL]",
      });
    } catch (dbErr) {
      // Non-blocking
    }

    return NextResponse.json({
      success: true,
      message: "Your message has been sent to our team at [EMAIL].",
    });
  } catch (err: any) {
    return NextResponse.json(
      { success: false, error: err.message || "Failed to submit inquiry" },
      { status: 500 }
    );
  }
}

