            pointsAwarded = 0; // Already awarded previously for this question
          }
        }
      } catch (dbErr) {
        console.warn("[DSA Progress Update DB Note]", dbErr);
      }
    } else if (isCorrect) {
      pointsAwarded = 25;
    }

    return NextResponse.json(
      {
        success: true,
