      );

      return NextResponse.json({
        success: true,
        jobs: res.rows,
      });
    } finally {
      client.release();
    }
  } catch (err: any) {
    console.error("[Employer Jobs GET Error]:", err);
    return NextResponse.json({ error: err.message || "Failed to fetch jobs" }, { status: 500 });
