      .eq("user_id", userId);

    if (error && error.code !== "PGRST116" && error.code !== "42P01") {
      console.warn("[Connected Accounts Fetch Warning]:", error.message);
    }

    const normalizedAccounts = (data || []).map((a: any) => ({
