import { NextRequest, NextResponse } from "next/server";
import { VOICE_PROFILES, VoiceChoice } from "@/lib/interview/voice-profiles";

export const dynamic = "force-dynamic";

// In-memory cache for synthesized speech metadata & static prompts
const TTS_AUDIO_CACHE = new Map<string, any>();

export async function POST(req: NextRequest) {
  try {
    const body = await req.json().catch(() => ({}));
    const { 
      text, 
      questionId, 
      voiceId = "elena-tech-lead", 
      speed = 1.0,
      candidateName = "Candidate",
      role = "Software Engineer",
      isIntro = false
    } = body;

    const chosenVoiceKey: VoiceChoice = VOICE_PROFILES[voiceId as VoiceChoice] ? (voiceId as VoiceChoice) : "elena-tech-lead";
    const voiceProfile = VOICE_PROFILES[chosenVoiceKey];

    let finalText = text;
    if (isIntro && voiceProfile.introGreeting) {
      finalText = voiceProfile.introGreeting(candidateName, role);
    }

    if (!finalText || typeof finalText !== "string") {
      return NextResponse.json(
        { error: "Text is required for TTS synthesis." }, 
        { status: 400 }
      );
    }

    // Clamp speed between 0.75x and 1.5x
    const numericSpeed = Math.min(Math.max(Number(speed) || 1.0, 0.75), 1.5);
    const finalRate = Math.round((voiceProfile.defaultRate * numericSpeed) * 100) / 100;

    const cacheKey = `${questionId || finalText.slice(0, 60)}_${chosenVoiceKey}_${finalRate}`;

    // Check cache
    if (TTS_AUDIO_CACHE.has(cacheKey)) {
      return NextResponse.json({
        success: true,
        cached: true,
        ...TTS_AUDIO_CACHE.get(cacheKey),
      });
    }

    // High quality speech synthesis parameters
    const synthesisData = {
      success: true,
      text: finalText,
      voiceId: voiceProfile.id,
      voiceName: voiceProfile.name,
      interviewerName: voiceProfile.interviewerName,
      roleTitle: voiceProfile.roleTitle,
      voiceHints: voiceProfile.voiceHints,
      rate: finalRate,
      pitch: voiceProfile.defaultPitch,
      bridgePhrases: voiceProfile.bridgePhrases,
      clientFallbackRequired: true,

      pitch: voiceProfile.defaultPitch,
      bridgePhrases: voiceProfile.bridgePhrases,
      clientFallbackRequired: true,
      availableVoices: Object.values(VOICE_PROFILES).map(v => ({
        id: v.id,
        name: v.name,
        interviewerName: v.interviewerName,
        roleTitle: v.roleTitle,
        accent: v.accent,
      })),
    };

    TTS_AUDIO_CACHE.set(cacheKey, synthesisData);

    return NextResponse.json(synthesisData);
  } catch (err: any) {
    return NextResponse.json({
      success: false,
      textOnlyFallback: true,
      error: err.message || "TTS error"
    });
  }
}

export async function GET() {
  return NextResponse.json({
    success: true,
    voices: Object.values(VOICE_PROFILES).map(v => ({
      id: v.id,
      name: v.name,
      interviewerName: v.interviewerName,
      roleTitle: v.roleTitle,
      accent: v.accent,
      defaultPitch: v.defaultPitch,
      defaultRate: v.defaultRate,
    })),
  });
}

import { NextRequest, NextResponse } from "next/server";
import { MyraInterviewPolicy, MYRA_INTERVIEWER_VERSION } from "@/lib/ai/myra-interview-policy";
import { supabase } from "@/lib/supabase";
import { rateLimit, getClientIp } from "@/lib/rate-limiter";
import { logger } from "@/lib/logger";

export const dynamic = "force-dynamic";

export async function POST(req: NextRequest) {
  const requestId = req.headers.get("x-request-id") || `req-${Date.now()}`;
  const log = logger.child({ request_id: requestId, route: "/api/interview/turn", service: "interview" });
  const startTime = Date.now();

  // Rate limit: 10 turns per minute per IP (AI endpoint — expensive to abuse)
  const ip = getClientIp(req);
  const rl = rateLimit(`interview-turn:${ip}`, { limit: 10, windowMs: 60_000 });
  if (!rl.allowed) {
    log.warn("Rate limit exceeded", { ip, limit: rl.limit });
    return NextResponse.json(
      { success: false, error: "Too many requests. Please wait before continuing." },
      {
        status: 429,
        headers: {
          "Retry-After": String(Math.ceil((rl.reset - Date.now()) / 1000)),
          "x-request-id": requestId,
        },
      }
    );
  }

  try {
    const body = await req.json().catch(() => ({}));
    const {
      questionText = "",
      candidateTranscript = "",
      isFollowUp = false,
      questionIndex = 0,
      totalQuestions = 3,
      targetRole = "Software Engineer",
      category = "Software Engineering",
      resumeContext = "",
      candidateName = "",
      userId = "anonymous",
      sessionId = "",
    } = body;

    if (!questionText) {
      return NextResponse.json(
        { error: "questionText is required." },
        { status: 400 }
      );
    }

    // Evaluate turn using Myra Interview Policy
    const turnResult = MyraInterviewPolicy.evaluateTurn({
      questionText,

    // Evaluate turn using Myra Interview Policy
    const turnResult = MyraInterviewPolicy.evaluateTurn({
      questionText,
      candidateTranscript: candidateTranscript || "",
      isFollowUp: Boolean(isFollowUp),
      questionIndex: Number(questionIndex) || 0,
      totalQuestions: Number(totalQuestions) || 3,
      targetRole,
      category,
      resumeContext,
      candidateName,
    });

    const latencyMs = Date.now() - startTime;

    // Log interaction to myra_interactions table
    if (userId && userId !== "anonymous" && userId !== "guest") {
      try {
        await supabase.from("myra_interactions").insert({
          user_id: userId,
          feature_context: isFollowUp ? "interview_follow_up" : "live_interview_turn",
          input_summary: candidateTranscript.slice(0, 300) || "[No speech / repeat request]",
          output_summary: turnResult.spokenText.slice(0, 300),
          model_version: turnResult.modelVersion || MYRA_INTERVIEWER_VERSION,
          status: "success",
          metadata: {
            action: turnResult.action,
            questionIndex,
            isFollowUp,
            latencyMs,
            sessionId,
            referencedPhrase: turnResult.referencedPhrase || null,
          },
        });
      } catch (logErr) {
        console.warn("[Myra Turn Log Warning]:", logErr);
      }
    }

    return NextResponse.json({
      success: true,
      action: turnResult.action,
      spokenText: turnResult.spokenText,
      followUpQuestion: turnResult.followUpQuestion || null,
      referencedPhrase: turnResult.referencedPhrase || null,
      reasoning: turnResult.reasoning,
      modelVersion: turnResult.modelVersion,
      latencyMs,
    });
  } catch (err: any) {
    console.error("[Myra Turn Error]:", err);
    // Graceful fallback turn so candidate interview never freezes or dead-ends
    return NextResponse.json({
      success: true,
      action: "next",
      spokenText: "Understood. Let's move to our next question.",
      reasoning: "Graceful recovery on internal processing exception.",
      modelVersion: MYRA_INTERVIEWER_VERSION,
      latencyMs: Date.now() - startTime,
    });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { supabase } from "@/lib/supabase";
import { rateLimit, getClientIp } from "@/lib/rate-limiter";

export async function GET(req: NextRequest) {
  try {
    const { searchParams } = new URL(req.url);
    const company = searchParams.get("company");
    const role = searchParams.get("role");
    const userId = req.headers.get("x-user-id");

    let query = supabase
      .from("interview_experiences")
      .select("*")
      .order("created_at", { ascending: false });

    if (company) {
      query = query.ilike("company", "%" + company + "%");
    }
    if (role) {
      query = query.ilike("role", "%" + role + "%");
    }

    const { data, error } = await query;
    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    const filtered = (data || []).filter((item: any) => {
      if (item.moderation_status === "approved") return true;
      if (userId && item.user_id === userId) return true;
      return false;
    });

    const sanitized = filtered.map((item: any) => {
      const isAuthor = userId && item.user_id === userId;
      return {
        id: item.id,
        company: item.company,
        role: item.role,
        rounds: item.rounds || [],
        overallNotes: item.overall_notes,
        difficultyRating: item.difficulty_rating || 3,
        isAnonymous: item.is_anonymous,
        moderationStatus: isAuthor ? item.moderation_status : "approved",
        createdAt: item.created_at,
        isAuthor,
        authorLabel: item.is_anonymous ? (isAuthor ? "You (Anonymous)" : "Anonymous Candidate") : (item.user_name || "Verified Candidate"),
      };
    });

    return NextResponse.json({ success: true, count: sanitized.length, experiences: sanitized });
  } catch (err: any) {

    return NextResponse.json({ success: true, count: sanitized.length, experiences: sanitized });
  } catch (err: any) {
    return NextResponse.json({ error: "FETCH_FAILED", message: err.message }, { status: 500 });
  }
}

export async function POST(req: NextRequest) {
  try {
    const ip = getClientIp(req);
    const limiter = rateLimit("exp_submit_" + ip, { limit: 10, windowMs: 60 * 1000 });
    if (!limiter.allowed) {
      return NextResponse.json({ error: "RATE_LIMIT_EXCEEDED" }, { status: 429 });
    }

    const body = await req.json();
    const { userId, company, role, rounds, overallNotes, difficultyRating, isAnonymous } = body;

    if (!company || !role || !overallNotes) {
      return NextResponse.json({ error: "MISSING_FIELDS", message: "Company, role, and overall notes are required." }, { status: 400 });
    }

    const { data, error } = await supabase.from("interview_experiences").insert({
      user_id: userId || null,
      company: company.trim(),
      role: role.trim(),
      rounds: rounds || [],
      overall_notes: overallNotes.trim(),
      difficulty_rating: difficultyRating || 3,
      is_anonymous: isAnonymous ?? true,
      moderation_status: "pending",
    }).select().single();

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({
      success: true,
      message: "Your interview experience was submitted for moderation. It will become visible once verified by our team.",
      experience: data,
    });
  } catch (err: any) {
    return NextResponse.json({ error: "SUBMISSION_FAILED", message: err.message }, { status: 500 });
  }
}

