import { NextRequest, NextResponse } from "next/server";
import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import { fetchSectorLandingData, SectorType } from "@/lib/services/landing-sector-service";

export const dynamic = "force-dynamic";

export async function GET(
  req: NextRequest,
  { params }: { params: { sector: string } }
) {
  try {
    const rawSector = params.sector;
    const sectorMap: Record<string, SectorType> = {
      "junior": "junior",
      "for-junior": "junior",
      "explorer": "explorer",
      "for-explorer": "explorer",
      "college": "college",
      "for-college": "college",
      "working_professional": "working_professional",
      "for-professionals": "working_professional",
      "professionals": "working_professional",
    };

    const sector = sectorMap[rawSector];
    if (!sector) {
      return NextResponse.json({ error: "Invalid sector" }, { status: 400 });
    }

    const cookieStore = cookies();
    const supabase = createServerClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
      {
        cookies: {
          get(name: string) {
            return cookieStore.get(name)?.value;
          },
        },
      }
    );

    const data = await fetchSectorLandingData(sector, supabase);
    return NextResponse.json({ success: true, data });
  } catch (error: any) {
    console.error(`GET /api/landing/${params.sector} error:`, error);
    return NextResponse.json({ error: error.message || "Failed to fetch sector landing data" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { queryDb } from "@/lib/db-server";

export const dynamic = "force-dynamic";

export async function GET(req: NextRequest) {
  try {
    const { searchParams } = new URL(req.url);
    const category = searchParams.get("category");
    const search = searchParams.get("search");

    let sql = `
      SELECT id, slug, title, tagline, category, level, duration_weeks, skills, icon_name, display_order, created_at,
             jsonb_array_length(roadmap) as phases_count,
             jsonb_array_length(resources) as resources_count,
             (quiz_spec->>'passing_score')::int as passing_score,
             jsonb_array_length(quiz_spec->'questions') as questions_count
      FROM public.courses
      WHERE is_active = true
    `;
    const params: any[] = [];

    if (category && category !== "All Fields" && category !== "all") {
      params.push(category);
      sql += ` AND category = $${params.length}`;
    }

    if (search && search.trim()) {
      params.push(`%${search.trim().toLowerCase()}%`);
      sql += ` AND (LOWER(title) LIKE $${params.length} OR LOWER(tagline) LIKE $${params.length} OR LOWER(category) LIKE $${params.length})`;
    }

    sql += ` ORDER BY display_order ASC, created_at ASC`;

    const { rows } = await queryDb(sql, params);

    return NextResponse.json({
      success: true,
      count: rows.length,
      courses: rows,
    });
  } catch (err: any) {
    console.error("[API Learn Courses Error]:", err);
    return NextResponse.json(
      { success: false, error: "Failed to retrieve courses catalog" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { queryDb } from "@/lib/db-server";

export const dynamic = "force-dynamic";

export async function GET(
  req: NextRequest,
  { params }: { params: { slug: string } }
) {
  try {
    const slug = params.slug;
    if (!slug) {
      return NextResponse.json({ success: false, error: "Course slug is required" }, { status: 400 });
    }

    const { rows } = await queryDb(
      `SELECT id, slug, title, tagline, category, level, duration_weeks, skills, icon_name,
              roadmap, resources, quiz_spec, display_order, created_at
       FROM public.courses
       WHERE slug = $1 AND is_active = true
       LIMIT 1`,
      [slug]
    );

    if (rows.length === 0) {
      return NextResponse.json({ success: false, error: "Course not found" }, { status: 404 });
    }

    const course = rows[0];

    // Sanitize quiz questions: do not send correct_index to client prior to evaluation
    const rawQuestions = course.quiz_spec?.questions || [];
    const clientQuestions = rawQuestions.map((q: any) => ({
      id: q.id,
      question: q.question,
      options: q.options,
    }));

    const sanitizedCourse = {
      ...course,
      quiz: {
        passingScore: course.quiz_spec?.passing_score || 75,
        totalQuestions: clientQuestions.length,
        questions: clientQuestions,
      },
    };
    delete sanitizedCourse.quiz_spec;

    return NextResponse.json({
      success: true,
      course: sanitizedCourse,
    });
  } catch (err: any) {
    console.error("[API Learn Course Detail Error]:", err);
    return NextResponse.json(
      { success: false, error: "Failed to retrieve course details" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { queryDb } from "@/lib/db-server";
import crypto from "crypto";

export const dynamic = "force-dynamic";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { slug, recipientName, userId, answers = {} } = body || {};

    if (!slug) {
      return NextResponse.json({ success: false, error: "Course slug is required." }, { status: 400 });
    }

    const trimmedName = (recipientName || "").trim();
    if (!trimmedName) {
      return NextResponse.json({ success: false, error: "Recipient name is required for certificate issuance." }, { status: 400 });
    }

    // 1. Fetch authoritative course and quiz_spec from PostgreSQL
    const { rows } = await queryDb(
      `SELECT id, slug, title, category, quiz_spec 
       FROM public.courses 
       WHERE slug = $1 AND is_active = true 
       LIMIT 1`,
      [slug]
    );

    if (rows.length === 0) {
      return NextResponse.json({ success: false, error: "Course not found." }, { status: 404 });
    }

    const course = rows[0];
    const questions: any[] = course.quiz_spec?.questions || [];
    const passingScore: number = course.quiz_spec?.passing_score || 75;

    if (questions.length === 0) {
      return NextResponse.json({ success: false, error: "No quiz configured for this course." }, { status: 400 });
    }

    // 2. Evaluate answers
    let correctCount = 0;
    const review = questions.map((q) => {
      const selectedIndex = answers[q.id];

    let correctCount = 0;
    const review = questions.map((q) => {
      const selectedIndex = answers[q.id];
      const isCorrect = selectedIndex === q.correct_index;
      if (isCorrect) correctCount++;

      return {
        id: q.id,
        question: q.question,
        selectedIndex,
        correctIndex: q.correct_index,
        isCorrect,
        explanation: q.explanation,
      };
    });

    const scorePercentage = Math.round((correctCount / questions.length) * 100);
    const passed = scorePercentage >= passingScore;

    let certificateRecord = null;

    // 3. If passed, issue verifiable certificate
    if (passed) {
      const randomSuffix = crypto.randomBytes(3).toString("hex").toUpperCase();
      const certificateCode = `EDW-CERT-2026-${randomSuffix}`;

      const payloadToHash = `${certificateCode}:${trimmedName}:${course.slug}:${scorePercentage}:${Date.now()}`;
      const verificationHash = crypto.createHash("sha256").update(payloadToHash).digest("hex");

      const insertRes = await queryDb(
        `INSERT INTO public.course_certificates (
          certificate_code, user_id, recipient_name, course_id, course_title, course_slug,
          course_category, score_percentage, passed, verification_hash, issued_at, metadata
        ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, true, $9, NOW(), $10)
        RETURNING id, certificate_code, recipient_name, course_title, course_slug, course_category,
                  score_percentage, passed, verification_hash, issued_at`,
        [
          certificateCode,
          userId || null,
          trimmedName,
          course.id,
          course.title,
          course.slug,
          course.category,
          scorePercentage,
          verificationHash,
          JSON.stringify({
            correctAnswers: correctCount,
            totalQuestions: questions.length,
            passingScoreThreshold: passingScore,
          }),
        ]
      );

      certificateRecord = insertRes.rows[0];
    }

    return NextResponse.json({
      success: true,
      passed,
      scorePercentage,
      passingScore,
      correctCount,
      totalCount: questions.length,
      certificate: certificateRecord,
      review,
    });
  } catch (err: any) {
    console.error("[API Quiz Submit Error]:", err);
    return NextResponse.json(
      { success: false, error: "Failed to evaluate quiz and issue certificate" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { executeMCPTool } from "@/lib/mcp/engine";
import { verifyUserRole } from "@/lib/server-role-guard";
import { MCPAuthContext } from "@/lib/mcp/types";
import { createClient } from "@/lib/supabase/server";
import { validateSession } from "@/lib/otp-service";

export const dynamic = "force-dynamic";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { tool, params } = body;

    if (!tool || typeof tool !== "string") {
      return NextResponse.json(
        { success: false, error: "Missing required 'tool' parameter." },
        { status: 400 }
      );
    }

    // Authenticate caller strictly from verified session
    let authenticatedUserId: string | null = null;
    let verifiedSessionRole: string | undefined = undefined;

    try {
      const supabaseServer = createClient();
      const { data: { user } } = await supabaseServer.auth.getUser();
      if (user?.id) {
        authenticatedUserId = user.id;
      }
    } catch {}

    if (!authenticatedUserId) {
      const sessionCookie = 
        req.cookies.get("edworld_session")?.value ||
        req.headers.get("authorization")?.replace(/^Bearer\s+/i, "");

      if (sessionCookie && sessionCookie.startsWith("edw_sess_")) {
        const sessRes = validateSession(sessionCookie);
        if (sessRes.valid && sessRes.userId) {
          authenticatedUserId = sessRes.userId;
          verifiedSessionRole = sessRes.role;
        }
      }
    }

    if (!authenticatedUserId) {
      return NextResponse.json(
        { success: false, error: "Unauthorized: Active authenticated session required to execute MCP tools." },
        { status: 401 }
      );
    }

    const userId = authenticatedUserId;
    const organizationId = req.headers.get("x-organization-id") || body.organizationId;
    const correlationId = req.headers.get("x-correlation-id") || `mcp_${Date.now()}`;

    const organizationId = req.headers.get("x-organization-id") || body.organizationId;
    const correlationId = req.headers.get("x-correlation-id") || `mcp_${Date.now()}`;

    // Validate database role & status (never trust client-supplied role claims blindly)
    const roleCheck = await verifyUserRole(userId, [
      "CLIENT", "EMPLOYEE", "HR", "FOUNDER", "EXECUTIVE", "TEACHER", "COLLEGE_ADMIN", "PLACEMENT_OFFICER", "ADMIN", "SUPER_ADMIN"
    ]);

    if (!roleCheck.authorized && roleCheck.statusCode === 401) {
      return NextResponse.json(
        { success: false, error: "Unauthorized: User not found." },
        { status: 401 }
      );
    }

    const verifiedRole = roleCheck.user?.role || "CLIENT";
    const authContext: MCPAuthContext = {
      userId,
      email: roleCheck.user?.email,
      role: verifiedRole,
      organizationId,
      correlationId,
      timestamp: new Date().toISOString()
    };

    // Execute MCP tool via central engine with full RBAC & audit logging
    const result = await executeMCPTool(tool, params || {}, authContext);

    return NextResponse.json(result, { status: result.statusCode || (result.success ? 200 : 400) });
  } catch (err: any) {
    console.error("[MCP Execute API Exception]:", err);
    return NextResponse.json(
      { success: false, error: `Internal MCP Execution Error: ${err.message}` },
      { status: 500 }
    );
  }
}

