export const dynamic = "force-dynamic";

export async function GET(req: NextRequest) {
  try {
    const userId = req.headers.get("x-user-id") || req.nextUrl.searchParams.get("userId");
    if (!userId) {
      return NextResponse.json({ success: true, recommendations: [], count: 0 });
    }

    // 1. Fetch current user's profile
    const { data: myProfile } = await supabase
      .from("profiles")
      .select("id, college, skills, interests, company, industry, career_stage, role")
      .eq("id", userId)
      .maybeSingle();

    if (!myProfile) {
      return NextResponse.json({ success: true, recommendations: [], count: 0 });
    }

    const mySkills: string[] = Array.isArray(myProfile.skills)
      ? myProfile.skills
      : (myProfile.interests || []).map((i: any) => (typeof i === "string" ? i : i.name || i.id));
    const myCollege = (myProfile.college || "").toLowerCase().trim();
    const myCompany = (myProfile.company || "").toLowerCase().trim();

    // 2. Fetch existing connections and blocked users to exclude
    const { data: conns } = await supabase
      .from("connections")
      .select("requester_id, receiver_id")
      .or(`requester_id.eq.${userId},receiver_id.eq.${userId}`);

    const { data: blocks } = await supabase
      .from("user_blocks")
      .select("blocker_id, blocked_id")
      .or(`blocker_id.eq.${userId},blocked_id.eq.${userId}`);

    const excludeIds = new Set<string>([userId]);
    (conns || []).forEach((c: any) => {
      excludeIds.add(c.requester_id);
      excludeIds.add(c.receiver_id);
    });
    (blocks || []).forEach((b: any) => {
      excludeIds.add(b.blocker_id);
      excludeIds.add(b.blocked_id);
    });

    // 3. Fetch potential discoverable candidates
    const { data: candidates } = await supabase
      .from("profiles")
      .select("id, name, username, headline, avatar_url, role, career_stage, college, degree, branch, company, industry, skills, interests, show_in_network, visibility")
      .neq("visibility", "PRIVATE")
      .neq("visibility", "private")

  .select("id, name, username, headline, avatar_url, role, career_stage, college, degree, branch, company, industry, skills, interests, show_in_network, visibility")
  .neq("visibility", "PRIVATE")
  .neq("visibility", "private")
  .limit(50);

if (!candidates || candidates.length === 0) {
  return NextResponse.json({ success: true, recommendations: [], count: 0 });
}

// 4. Score candidates based on REAL signals only (no random math)
const scoredList: Array<{ profile: any; score: number; reason: string }> = [];

for (const cand of candidates) {
  if (excludeIds.has(cand.id)) continue;
  if (cand.show_in_network === false) continue;

  let score = 0;
  let reasons: string[] = [];

  // Signal 1: Same College
  if (myCollege && cand.college && cand.college.toLowerCase().trim() === myCollege) {
    score += 3;
    reasons.push(`Also from ${cand.college}`);
  }

  // Signal 2: Same Company
  if (myCompany && cand.company && cand.company.toLowerCase().trim() === myCompany) {
    score += 3;
    reasons.push(`Also at ${cand.company}`);
  }

  // Signal 3: Overlapping skills
  const candSkills: string[] = Array.isArray(cand.skills)
    ? cand.skills
    : (cand.interests || []).map((i: any) => (typeof i === "string" ? i : i.name || i.id));

  const sharedSkills = mySkills.filter((s) =>
    candSkills.some((cs) => cs.toLowerCase() === s.toLowerCase())
  );

  if (sharedSkills.length > 0) {
    score += sharedSkills.length * 2;
    reasons.push(`Shares ${sharedSkills.slice(0, 2).join(", ")}`);
  }

  // ONLY include candidates who have at least one real matching signal (score > 0)
  if (score > 0) {

      // ONLY include candidates who have at least one real matching signal (score > 0)
      if (score > 0) {
        const isStudent = (cand.role || "").toUpperCase() === "STUDENT" || Boolean(cand.college && !cand.company);
        scoredList.push({
          profile: {
            userId: cand.id,
            username: cand.username || cand.name?.toLowerCase().replace(/\s+/g, "_") || cand.id.slice(0, 8),
            name: cand.name || "EdWorld Member",
            avatarUrl: cand.avatar_url || null,
            headline: cand.headline || (isStudent ? "Student" : "Working Professional"),
            college: cand.college,
            company: cand.company,
            userType: isStudent ? "STUDENT" : "WORKING_PROFESSIONAL",
            skills: candSkills.slice(0, 4),
            connectionStatus: "none"
          },
          score,
          reason: reasons.join(" • ")
        });
      }
    }

    // Sort by signal strength descending
    scoredList.sort((a, b) => b.score - a.score);

    return NextResponse.json({
      success: true,
      recommendations: scoredList.slice(0, 6).map((item) => ({
        ...item.profile,
        matchReason: item.reason
      })),
      count: scoredList.length
    });
  } catch (err: any) {
    return NextResponse.json({ success: false, error: err.message || "Internal error" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { supabase } from "@/lib/supabase";
import { forwardSafetyReport } from "@/lib/email-service";

export const dynamic = "force-dynamic";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const reporterId = req.headers.get("x-user-id") || body.reporterId || body.userId;
    const reportedId = body.reportedId || body.targetId;
    const category = body.category || body.type || "profile";
    const reason = body.reason || "Policy violation";
    const details = body.details || "";

    if (!reporterId || !reportedId) {
      return NextResponse.json({ success: false, error: "Missing reporter or reported user ID." }, { status: 400 });
    }

    if (reporterId === reportedId) {
      return NextResponse.json({ success: false, error: "Cannot report your own account." }, { status: 400 });
    }

    const { data: reportRecord, error } = await supabase
      .from("user_reports")
      .insert({
        reporter_id: reporterId,
        reported_id: reportedId,
        category,
        reason,
        details: details || null,
        status: "PENDING"
      })
      .select()
      .single();

    if (error) {
      return NextResponse.json({ success: false, error: error.message }, { status: 500 });
    }

    // Forward report notification directly to [EMAIL]
    await forwardSafetyReport({
      reporterId,
      targetId: reportedId,
      category,
      reason,
      details,
    });

    return NextResponse.json({ success: true, report: reportRecord, message: "Report submitted for moderation review." });
  } catch (err: any) {
    return NextResponse.json({ success: false, error: err.message || "Internal error" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { supabase } from "@/lib/supabase";

export const dynamic = "force-dynamic";

/**
 * GET /api/network/upcoming-birthdays?userId=<uid>
 * Returns connection birthdays occurring today or within the next 7 days.
 * Privacy Guaranteed:
 * - Returns ONLY (connection_user_id, name, month, day, is_today, days_until, has_wished).
 * - Never returns birth year, raw DOB, or computed age.
 * - Only includes accepted connections who explicitly opted-in (show_birthday_to_connections = true).
 */
export async function GET(req: NextRequest) {
  try {
    const { searchParams } = new URL(req.url);
    const userId = searchParams.get("userId");

    if (!userId) {
      return NextResponse.json({ error: "userId parameter is required" }, { status: 400 });
    }

    const now = new Date();
    const currentMonth = now.getMonth() + 1; // 1-12
    const currentDay = now.getDate();
    const currentYear = now.getFullYear();

    // 1. Attempt using Security Definer RPC
    try {
      const { data: rpcData, error: rpcError } = await supabase.rpc("get_upcoming_connection_birthdays", {
        requesting_user_id: userId,
      });

      if (!rpcError && rpcData && Array.isArray(rpcData)) {
        // Calculate days until birthday for each connection (within 7 day window)
        const enriched = rpcData
          .map((b: any) => {
            const bMonth = b.month;
            const bDay = b.day;

            // Calculate days remaining in current year or next
            let nextDate = new Date(currentYear, bMonth - 1, bDay);

        // Calculate days remaining in current year or next
        let nextDate = new Date(currentYear, bMonth - 1, bDay);
        if (nextDate < new Date(currentYear, currentMonth - 1, currentDay)) {
          nextDate = new Date(currentYear + 1, bMonth - 1, bDay);
        }

        const diffTime = nextDate.getTime() - new Date(currentYear, currentMonth - 1, currentDay).getTime();
        const daysUntil = Math.round(diffTime / (1000 * 60 * 60 * 24));

        return {
          connection_user_id: b.connection_user_id,
          name: b.name || "Connection",
          month: bMonth,
          day: bDay,
          is_today: b.is_today || (bMonth === currentMonth && bDay === currentDay),
          days_until: daysUntil,
          has_wished: Boolean(b.has_wished),
        };
      })
      .filter((b) => b.days_until >= 0 && b.days_until <= 7)
      .sort((a, b) => a.days_until - b.days_until);

    return NextResponse.json({ birthdays: enriched });
  }
} catch (rpcErr) {
  console.warn("[RPC upcoming_birthdays warning, using resilient fallback]:", rpcErr);
}

// 2. Resilient Fallback Query: Join profiles & accepted connections
const { data: connections, error: connErr } = await supabase
  .from("connections")
  .select("requester_id, receiver_id, status")
  .or(`requester_id.eq.${userId},receiver_id.eq.${userId}`)
