const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
  e.preventDefault();
  const pasted = e.clipboardData.getData("text/plain").trim();
  if (!/^\d+$/.test(pasted)) return;

  const chars = pasted.slice(0, 6).split("");
  const newDigits = Array(6).fill("");
  chars.forEach((c, i) => {
    newDigits[i] = c;
