const handlePreFlightProceed = async (config: {
  audioOptIn: boolean;
  voiceChoice: VoiceChoice;
  speakingSpeed: number;
  companyTrack?: string;
  isAudioOnly: boolean;
  useKeyboardFallback: boolean;
}) => {
