      const dateB = new Date(b.postedAt || b.createdAt).getTime();
      return dateB - dateA;
    });
}, [scoredJobs, searchTerm, selectedType, selectedCategory, selectedSource, minMatchThreshold, sortByMatch, isAdult]);

