    });

    const orderData = await orderRes.json();

    if (orderData.success && orderData.keyId !== "rzp_test_mock_key_id") {
      const loaded = await loadRazorpayScript();
      if (loaded && (window as any).Razorpay) {
        const options = {
          key: orderData.keyId,
