          {renderInlineTokens(line.replace(/^###\s+/, ""))}
        </h4>
      );
      i++;
      continue;
    }

    if (line.startsWith("#### ")) {
      elements.push(
        <h5 key={`h4-${blockKey}-${i}`} className="font-bold text-slate-200 text-xs sm:text-sm mt-2.5 mb-0.5 font-display">
