      const matchCategory = p.category.toLowerCase().includes(q);
      const matchSkills = p.typical_skills.some((s) => s.toLowerCase().includes(q));
      return matchName || matchDesc || matchCategory || matchSkills;
    });

    if (matchingPaths.length > 0) {
      result.push({
        name: cat.name,
        paths: matchingPaths,
      });
    }
  }
  return result;
