          userId,
          preference: newPref,
        }),
      });

      if (res.ok) {

    });

    if (res.ok) {
      setSaveSuccess(true);
      onLayoutSaved(newPref);
      setTimeout(() => {
        setSaveSuccess(false);
        onClose();
      }, 1200);
    }
  } catch (err) {
    console.error("[Dashboard Customization Save Error]:", err);
  } finally {
    setIsSaving(false);
  }
};

const handleReset = async () => {
  setIsSaving(true);
  try {
    const res = await fetch(`/api/profile/dashboard-layout?userId=${userId}`, {
      method: "DELETE",
    });

    if (res.ok) {
      onResetToDefaults();
      onClose();
