interface VoiceDictationModalProps {
  isOpen: boolean;
  fieldLabel: string;
  initialText?: string;
  onApply: (text: string) => void;
  onClose: () => void;
}

export function VoiceDictationModal({
  isOpen,
  fieldLabel,
  initialText = "",
  onApply,
  onClose,
}: VoiceDictationModalProps) {
  const [isRecording, setIsRecording] = useState(false);
  const [transcript, setTranscript] = useState(initialText);
  const [speechSupported, setSpeechSupported] = useState(true);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    if (!isOpen) {
      stopRecording();
      return;
    }
    setTranscript(initialText);

    // Initialize Web Speech API
    if (typeof window !== "undefined") {
      const SpeechRec = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (SpeechRec) {
        const recog = new SpeechRec();
        recog.continuous = true;
        recog.interimResults = true;
        recog.lang = "en-US";

        recog.onresult = (event: any) => {
          let full = "";
          for (let i = 0; i < event.results.length; i++) {
            full += event.results[i][0].transcript + " ";
          }
          setTranscript(full.trim());
        };

        recog.onerror = (err: any) => {
          console.warn("[Dictation Recognition Error]:", err?.error);
        };

        recognitionRef.current = recog;
      } else {
        setSpeechSupported(false);
      }
    }

    return () => {
      stopRecording();
    };
  }, [isOpen, initialText]);

  const startRecording = () => {
    if (!recognitionRef.current) return;
    try {
      recognitionRef.current.start();
      setIsRecording(true);
    } catch (e) {
      console.warn("Recog start note:", e);
    }
  };

  }
};

const stopRecording = () => {
  if (recognitionRef.current) {
    try { recognitionRef.current.stop(); } catch (e) {}
  }
  setIsRecording(false);
};

const handleApply = () => {
  stopRecording();
  onApply(transcript.trim());
  onClose();
};

if (!isOpen) return null;

return (
  <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in">
    <div className="bg-white rounded-3xl border border-neutral-200 shadow-2xl max-w-lg w-full p-6 space-y-4 text-black">

