import React, { useMemo } from "react";

interface QrCodeViewProps {
  value: string;
  size?: number;
  fgColor?: string;
  bgColor?: string;
  className?: string;
  includeMargin?: boolean;
}

/**
 * Lightweight, zero-dependency QR code SVG renderer using standard QR matrix generation.
 * Generates valid scannable QR codes for URLs and text.
 */
export function QrCodeView({
  value,
  size = 140,
  fgColor = "#000000",
  bgColor = "#FFFFFF",
  className = "",
  includeMargin = true,
}: QrCodeViewProps) {
  const matrix = useMemo(() => {
    return generateQrMatrix(value);
  }, [value]);

  const moduleCount = matrix.length;
  const margin = includeMargin ? 2 : 0;
  const totalCount = moduleCount + margin * 2;

  return (
    <svg
      viewBox={`0 0 ${totalCount} ${totalCount}`}
      width={size}
      height={size}
      className={`shrink-0 ${className}`}
      shapeRendering="crispEdges"
      role="img"
      aria-label={`QR Code for ${value}`}
    >
      <rect width={totalCount} height={totalCount} fill={bgColor} />
      {matrix.map((row, r) =>
        row.map((cell, c) => {
          if (!cell) return null;
          return (
            <rect
              key={`${r}-${c}`}
              x={c + margin}
              y={r + margin}
              width={1}
              height={1}
              fill={fgColor}
            />
          );
        })
      )}
    </svg>
  );
}

