function encodeUtf8(str: string): number[] {
  const bytes: number[] = [];
  for (let i = 0; i < str.length; i++) {
    let code = str.charCodeAt(i);
    if (code < 0x80) {
      bytes.push(code);
    } else if (code < 0x800) {
      bytes.push(0xc0 | (code >> 6));
      bytes.push(0x80 | (code & 0x3f));
    } else {
      bytes.push(0xe0 | (code >> 12));
      bytes.push(0x80 | ((code >> 6) & 0x3f));
      bytes.push(0x80 | (code & 0x3f));
    }
  }
  return bytes;
}

function appendBits(arr: number[], value: number, length: number) {
  for (let i = length - 1; i >= 0; i--) {
    arr.push((value >> i) & 1);
  }
}

function placeFinderPattern(grid: (boolean | null)[][], row: number, col: number) {
  for (let r = -1; r <= 7; r++) {
    for (let c = -1; c <= 7; c++) {
      const gr = row + r;
      const gc = col + c;
      if (gr < 0 || gr >= grid.length || gc < 0 || gc >= grid.length) continue;
      if (
        (r >= 0 && r <= 6 && (c === 0 || c === 6)) ||

      if (gr < 0 || gr >= grid.length || gc < 0 || gc >= grid.length) continue;
      if (
        (r >= 0 && r <= 6 && (c === 0 || c === 6)) ||
        (c >= 0 && c <= 6 && (r === 0 || r === 6)) ||
        (r >= 2 && r <= 4 && c >= 2 && c <= 4)
      ) {
        grid[gr][gc] = true;
      } else {
        grid[gr][gc] = false;
      }
    }
  }
}

function placeAlignmentPattern(grid: (boolean | null)[][], row: number, col: number) {
  for (let r = -2; r <= 2; r++) {
    for (let c = -2; c <= 2; c++) {
      const gr = row + r;
      const gc = col + c;
      if (grid[gr][gc] !== null) continue;
      if (
        Math.abs(r) === 2 ||
        Math.abs(c) === 2 ||
        (r === 0 && c === 0)
      ) {
        grid[gr][gc] = true;
      } else {
        grid[gr][gc] = false;
      }
    }
