  from?: string;
  to?: string | string[];
  cc?: string | string[];
  bcc?: string | string[];
  subject: string;
  html: string;
  text?: string;
  category?: "contact" | "report" | "auth" | "ambassador" | "interview" | "application" | "system" | "newsletter" | "certificate";
  metadata?: Record<string, any>;
}

