const DISCRIMINATORY_PATTERNS = [
  /\b(how old are you|what is your age|date of birth)\b/i,
  /\b(are you married|marital status|spouse|husband|wife)\b/i,
  /\b(religion|caste|faith|god|praying|temple|church|mosque)\b/i,
